/// The winking-cat logo (generated by tool/make_icon.py into assets/brand).
class CatLogo extends StatelessWidget {
  const CatLogo({super.key, this.size = 40});
  final double size;

  @override
  Widget build(BuildContext context) {
    return Image.asset(
      'assets/brand/splash.png',
      width: size,
      height: size,
      errorBuilder: (_, __, ___) => Icon(Icons.pets, size: size * 0.8, color: BrandColors.amber),
    );
  }
}

