class SectionTitle extends StatelessWidget {
  const SectionTitle(this.text, {super.key, this.trailing, this.icon});
  final String text;
  final Widget? trailing;
  final IconData? icon;

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.fromLTRB(16, 22, 16, 8),
      child: Row(
        children: [
          if (icon != null) ...[
            Icon(icon, size: 20, color: BrandColors.amber),
            const SizedBox(width: 8),
          ],
          Expanded(
            child: Text(text, style: Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight: FontWeight.w800)),
          ),
          if (trailing != null) trailing!,
        ],
      ),
    );
  }
}

class OutlinedCard extends StatelessWidget {
  const OutlinedCard(
      {super.key, required this.child, this.padding = const EdgeInsets.all(16), this.color, this.borderColor, this.gradient});
  final Widget child;
  final EdgeInsets padding;
  final Color? color;
  final Color? borderColor;
  final Gradient? gradient;

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;
    return Container(
      margin: const EdgeInsets.symmetric(horizontal: 16, vertical: 6),
      padding: padding,
      decoration: BoxDecoration(
        color: gradient == null ? (color ?? scheme.surface) : null,
        gradient: gradient,
        borderRadius: BorderRadius.circular(18),
        border: Border.all(color: borderColor ?? scheme.outlineVariant.withValues(alpha: 0.6)),
        boxShadow: [BoxShadow(color: Colors.black.withValues(alpha: 0.04), blurRadius: 12, offset: const Offset(0, 4))],
      ),
      child: child,
    );
  }
}

/// Branded stand-in for a product photo until retailer feeds supply images.
class ProductImage extends StatelessWidget {
  const ProductImage({super.key, required this.variant, this.size = 72, this.radius = 16});
  final Variant variant;
  final double size;
  final double radius;

  @override
  Widget build(BuildContext context) {
    final c = variant.category.color;
    return Container(
      width: size,
      height: size,
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(radius),
        gradient: LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: [c, Color.lerp(c, BrandColors.indigo, 0.55)!],
        ),
      ),
      child: Stack(
        children: [
          Positioned(
            right: -size * 0.12,
            bottom: -size * 0.12,
            child: Icon(variant.category.icon, size: size * 0.8, color: Colors.white.withValues(alpha: 0.22)),
          ),
          Center(child: Icon(variant.category.icon, size: size * 0.42, color: Colors.white)),
          if (size >= 64)
            Positioned(
              left: 8,
              top: 6,
              right: 8,
              child: Text(
                variant.brand.toUpperCase(),
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: TextStyle(
                    color: Colors.white, fontWeight: FontWeight.w800, fontSize: size * 0.11, letterSpacing: 0.8),
              ),
            ),
        ],
      ),
    );
  }
}

class RatingStars extends StatelessWidget {
  const RatingStars({super.key, required this.rating, this.size = 14, this.count});
  final double rating;
  final double size;
  final int? count;

  @override
  Widget build(BuildContext context) {
    final full = rating.floor();
    final half = rating - full >= 0.5;
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        for (var i = 0; i < 5; i++)
          Icon(
            i < full
                ? Icons.star_rounded
                : (i == full && half ? Icons.star_half_rounded : Icons.star_outline_rounded),
            size: size,
            color: BrandColors.amber,
          ),
        const SizedBox(width: 4),
        Text(rating.toStringAsFixed(1), style: TextStyle(fontSize: size * 0.9, fontWeight: FontWeight.w700)),
        if (count != null)
          Text(' ($count)', style: TextStyle(fontSize: size * 0.85, color: Theme.of(context).colorScheme.onSurfaceVariant)),
      ],
    );
  }
}

class Pill extends StatelessWidget {
  const Pill(this.text, {super.key, required this.color, required this.background, this.icon});
