  }
}

/// Price history line with a soft fill; no chart dependency needed.
class Sparkline extends StatelessWidget {
  const Sparkline({super.key, required this.points, this.height = 110});
  final List<PricePoint> points;
  final double height;

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      height: height,
      width: double.infinity,
      child: CustomPaint(painter: _SparkPainter(points, Theme.of(context).colorScheme.primary)),
    );
  }
}

class _SparkPainter extends CustomPainter {
  _SparkPainter(this.points, this.color);
  final List<PricePoint> points;
  final Color color;

  @override
  void paint(Canvas canvas, Size size) {
    if (points.length < 2) return;
    final prices = points.map((p) => p.lowestPrice).toList();
    final lo = prices.reduce((a, b) => a < b ? a : b).toDouble();
    final hi = prices.reduce((a, b) => a > b ? a : b).toDouble();
    final span = (hi - lo) == 0 ? 1.0 : hi - lo;
    double yOf(int p) => size.height - (p - lo) / span * (size.height - 12) - 6;
    final line = Path();
    for (var i = 0; i < prices.length; i++) {
      final x = size.width * i / (prices.length - 1);
      if (i == 0) {
        line.moveTo(x, yOf(prices[i]));
      } else {
        line.lineTo(x, yOf(prices[i]));
      }
    }
    final fill = Path.from(line)
      ..lineTo(size.width, size.height)
      ..lineTo(0, size.height)
      ..close();
    canvas.drawPath(
      fill,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [color.withValues(alpha: 0.25), color.withValues(alpha: 0.0)],
        ).createShader(Offset.zero & size),
    );
    canvas.drawPath(
      line,
      Paint()
        ..color = color
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2.2,
    );
    canvas.drawCircle(Offset(size.width - 2, yOf(prices.last)), 5, Paint()..color = BrandColors.amber);
  }

  @override
  bool shouldRepaint(covariant _SparkPainter old) => old.points != points || old.color != color;
}

class ScoreRow extends StatelessWidget {
  const ScoreRow({super.key, required this.dimension});
  final ReportDimension dimension;

  @override
  Widget build(BuildContext context) {
    final d = dimension;
    final scheme = Theme.of(context).colorScheme;
    final conf = switch (d.confidence) {
      Confidence.high => 'High confidence',
      Confidence.medium => 'Medium confidence',
      Confidence.low => 'Low confidence',
      null => 'Not scored',
    };
    final barColor = d.score == null
        ? scheme.outlineVariant
        : d.score! >= 8.5
            ? BrandColors.emerald
            : d.score! >= 7.5
                ? BrandColors.indigoMid
                : BrandColors.amber;
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 8),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Expanded(child: Text(d.name, style: const TextStyle(fontWeight: FontWeight.w700))),
              Text(
                d.score == null ? 'Not enough evidence' : '${d.score!.toStringAsFixed(1)} / 10',
                style: TextStyle(fontWeight: FontWeight.w800, color: d.score == null ? scheme.onSurfaceVariant : barColor),
              ),
            ],
          ),
          const SizedBox(height: 6),
          ClipRRect(
            borderRadius: BorderRadius.circular(6),
            child: LinearProgressIndicator(
              value: (d.score ?? 0) / 10,
              minHeight: 8,
              color: barColor,
              backgroundColor: scheme.surfaceContainerHighest,
            ),
          ),
          const SizedBox(height: 6),
          Text(d.summary, style: Theme.of(context).textTheme.bodySmall),
          Text('$conf · ${d.evidenceCount} sources',
              style: Theme.of(context).textTheme.labelSmall?.copyWith(color: scheme.onSurfaceVariant)),
        ],
      ),
    );
  }
}
